describe('User Profile - Change Password', () => {
  const testUser = {
    email: 'testuser@example.com',
    currentPassword: 'CurrentPassword123!',
    newPassword: 'NewPassword456!',
    confirmPassword: 'NewPassword456!'
  };

  beforeEach(() => {
    cy.visit('/login');
    cy.get('input[name="email"]').type(testUser.email);
    cy.get('input[name="password"]').type(testUser.currentPassword);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');
    cy.visit('/profile/settings');
    cy.get('[data-testid="profile-settings-page"]').should('be.visible');
  });

  it('should successfully change password with valid credentials', () => {
    cy.get('[data-testid="change-password-section"]').should('be.visible');
    cy.get('[data-testid="change-password-btn"]').click();

    cy.get('[data-testid="current-password-input"]').should('be.visible');
    cy.get('[data-testid="current-password-input"]').type(testUser.currentPassword);

    cy.get('[data-testid="new-password-input"]').type(testUser.newPassword);
    cy.get('[data-testid="confirm-password-input"]').type(testUser.confirmPassword);

    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Strong');

    cy.get('[data-testid="submit-password-change-btn"]').click();

    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Password changed successfully');

    cy.get('[data-testid="change-password-modal"]').should('not.exist');
  });

  it('should display error when current password is incorrect', () => {
    cy.get('[data-testid="change-password-btn"]').click();

    cy.get('[data-testid="current-password-input"]').type('WrongPassword123!');
    cy.get('[data-testid="new-password-input"]').type(testUser.newPassword);
    cy.get('[data-testid="confirm-password-input"]').type(testUser.confirmPassword);

    cy.get('[data-testid="submit-password-change-btn"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Current password is incorrect');
    cy.get('[data-testid="change-password-modal"]').should('be.visible');
  });

  it('should display error when new passwords do not match', () => {
    cy.get('[data-testid="change-password-btn"]').click();

    cy.get('[data-testid="current-password-input"]').type(testUser.currentPassword);
    cy.get('[data-testid="new-password-input"]').type(testUser.newPassword);
    cy.get('[data-testid="confirm-password-input"]').type('DifferentPassword789!');

    cy.get('[data-testid="submit-password-change-btn"]').click();

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Passwords do not match');
  });

  it('should display validation error for weak password', () => {
    cy.get('[data-testid="change-password-btn"]').click();

    cy.get('[data-testid="current-password-input"]').type(testUser.currentPassword);
    cy.get('[data-testid="new-password-input"]').type('weak');
    cy.get('[data-testid="confirm-password-input"]').type('weak');

    cy.get('[data-testid="password-strength-indicator"]').should('contain', 'Weak');
    cy.get('[data-testid="submit-password-change-btn"]').should('be.disabled');
  });

  it('should require all password fields to be filled', () => {
    cy.get('[data-testid="change-password-btn"]').click();

    cy.get('[data-testid="current-password-input"]').type(testUser.currentPassword);
    cy.get('[data-testid="new-password-input"]').type(testUser.newPassword);

    cy.get('[data-testid="submit-password-change-btn"]').should('be.disabled');

    cy.get('[data-testid="confirm-password-input"]').type(testUser.confirmPassword);
    cy.get('[data-testid="submit-password-change-btn"]').should('not.be.disabled');
  });

  it('should allow user to cancel password change', () => {
    cy.get('[data-testid="change-password-btn"]').click();
    cy.get('[data-testid="change-password-modal"]').should('be.visible');

    cy.get('[data-testid="cancel-password-change-btn"]').click();
    cy.get('[data-testid="change-password-modal"]').should('not.exist');
  });

  it('should clear form fields after successful password change', () => {
    cy.get('[data-testid="change-password-btn"]').click();

    cy.get('[data-testid="current-password-input"]').type(testUser.currentPassword);
    cy.get('[data-testid="new-password-input"]').type(testUser.newPassword);
    cy.get('[data-testid="confirm-password-input"]').type(testUser.confirmPassword);

    cy.get('[data-testid="submit-password-change-btn"]').click();
    cy.get('[data-testid="success-message"]').should('be.visible');

    cy.get('[data-testid="change-password-btn"]').click();
    cy.get('[data-testid="current-password-input"]').should('have.value', '');
    cy.get('[data-testid="new-password-input"]').should('have.value', '');
    cy.get('[data-testid="confirm-password-input"]').should('have.value', '');
  });
});
